PAT=re.compile(r'(?<!\d)(\d{5})\s*(?:\.\s*){0,5}([act])?\s*(?:\.\s*){0,5}(\d{3,9})(?!\d)')

def native_rows(pdf):
    doc=fitz.open(stream=pdf,filetype='pdf');out=[]
    for page_no,page in enumerate(doc,1):
        txt=page.get_text('text',sort=False)
        for m in PAT.finditer(txt):
            n,mark,amt=m.groups()
            if int(amt)>100000000:continue
            out.append({'numero':n,'marca':mark or '', 'euros_billete':int(amt), 'pagina':page_no,
              'contexto':txt[max(0,m.start()-38):min(len(txt),m.end()+38)].replace('\n',' ')})
    return out

def alternative_rows(pdf):
    import subprocess,tempfile
    with tempfile.TemporaryDirectory() as tmp:
        p=pathlib.Path(tmp)/'doc.pdf';p.write_bytes(pdf)
        txt=subprocess.run(['pdftotext','-raw',str(p),'-'],capture_output=True,text=True,check=True).stdout
    pat=re.compile(r'^\s*(\d{5})\s*(?:\.\s*){1,6}(?:([act])\s*(?:\.\s*)*)?(\d{1,3}(?:[. ]\d{3})*|\d{4,8})\s*$',re.M)
    return [{'numero':m[1],'marca':m[2] or '', 'euros_billete':int(m[3].replace('.','').replace(' ',''))} for m in pat.finditer(txt)]

def main():
    assets=pickle.loads(zlib.decompress(base64.b85decode(PAYLOAD)))
    out=pathlib.Path('salida_106');out.mkdir(exist_ok=True)
    summary={'version':'1.06','fecha_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),
      'fuente':'PDF y catalogos historicos conservados de SELAE; sin consultas de red',
      'publicable':False,'motor_validado':False,'catalogo_validado':False,'historico_modificado':False,'anios':{}}
    for y in (2024,2025):
        pdf=assets[f'pdf_{y}'];cat=json.loads(assets[f'catalog_{y}']);native=native_rows(pdf);alt=alternative_rows(pdf)
        native_map=collections.defaultdict(list)
        for r in native:
            if r['marca']=='' and r['euros_billete']==1000:native_map[r['numero']].append(r)
        alt_set={r['numero'] for r in alt if r['marca']=='' and r['euros_billete']==1000}
        catalog_map={r['numero']:r for r in cat['candidatos']}
        native_set=set(native_map);catalog_set=set(catalog_map)
        recovered=sorted(native_set-alt_set)
        evidence=[]
        for n in recovered:
            records=native_map[n];original=catalog_map.get(n)
            evidence.append({'numero':n,'recuperado_por_lector_nativo':True,
              'paginas_pdf':sorted({r['pagina'] for r in records}),
              'importe_euros_billete':1000,'marca':'',
              'contexto_pdf_nativo':records[0]['contexto'],
              'presente_en_catalogo_103':n in catalog_set,
              'paginas_catalogo_103':original.get('paginas',[]) if original else [],
              'coincide_pagina_catalogo':bool(original and set(original.get('paginas',[])) & {r['pagina'] for r in records}),
              'apariciones_nativas':len(records),'estado':'EVIDENCIA_PDF_SIN_VALIDACION_INDEPENDIENTE'})
        sha=hashlib.sha256(pdf).hexdigest();expected=cat['resumen']['sha256_pdf']
        audit={'anio':y,'sha256_pdf':sha,'sha256_catalogo_103':expected,
          'sha256_coincide':sha==expected,'candidatos_catalogo_103':len(catalog_set),
          'candidatos_lector_nativo':len(native_set),'candidatos_lector_alternativo':len(alt_set),
          'recuperados_por_lector_nativo':len(recovered),
          'recuperados_todos_presentes_catalogo':all(n in catalog_set for n in recovered),
          'recuperados_con_pagina_concordante':sum(e['coincide_pagina_catalogo'] for e in evidence),
          'solo_catalogo_vs_nativo':sorted(catalog_set-native_set),
          'solo_nativo_vs_catalogo':sorted(native_set-catalog_set),
          'solo_alternativo_vs_nativo':sorted(alt_set-native_set),
          'duplicados_nativos':{n:len(v) for n,v in native_map.items() if len(v)>1},
          'evidencias_recuperadas':evidence,
          'conclusion':'La omision del lector alternativo se reconcilia contra el PDF nativo; no es una validacion independiente de premios.'}
        (out/f'auditoria_recuperacion_navidad_{y}_106.json').write_text(json.dumps(audit,ensure_ascii=False,indent=2),encoding='utf-8')
        (out/f'numeros_recuperados_navidad_{y}_106.txt').write_text('\n'.join(recovered)+'\n',encoding='utf-8')
        summary['anios'][str(y)]={k:audit[k] for k in ('sha256_coincide','candidatos_catalogo_103','candidatos_lector_nativo','candidatos_lector_alternativo','recuperados_por_lector_nativo','recuperados_todos_presentes_catalogo','recuperados_con_pagina_concordante')}
        summary['anios'][str(y)]['discrepancias_restantes_catalogo_nativo']=len(audit['solo_catalogo_vs_nativo'])+len(audit['solo_nativo_vs_catalogo'])
        print(y,summary['anios'][str(y)])
    summary['reconciliacion_completa']=all(v['sha256_coincide'] and v['discrepancias_restantes_catalogo_nativo']==0 and v['recuperados_todos_presentes_catalogo'] and v['recuperados_con_pagina_concordante']==v['recuperados_por_lector_nativo'] for v in summary['anios'].values())
    summary['advertencia']='Reconciliacion entre dos lecturas del mismo PDF; no certifica la pedrea ni los importes.'
    (out/'informe_navidad_106.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2),encoding='utf-8')
    if not summary['reconciliacion_completa']:raise SystemExit('Discrepancias sin resolver; revisar informe')
if __name__=='__main__':main()
